window.RI2_UNITS = {"4":{"unit":4,"code":"RI2-U04","title":"TRADITIONS & RITUALS","startNumber":93,"endNumber":117,"entries":[{"number":93,"term":"ritual","sourceTerm":"ritual (n)","spoken":"ritual","ipa":"ritual /ˈrɪtʃuəl/","type":"noun","meaning":"nghi thức, nghi lễ","definition":"A fixed series of actions performed for a religious, cultural, or social purpose.","note":"Ritual nhấn mạnh chuỗi hành động theo nghi thức, thường được thực hiện theo một trật tự cố định.","example":"The harvest ritual brings the whole community together each autumn."},{"number":94,"term":"heritage","sourceTerm":"heritage (n)","spoken":"heritage","ipa":"heritage /ˈhɛrətədʒ/","type":"noun","meaning":"di sản","definition":"Traditions, values, places, and objects received from earlier generations.","note":"Heritage thường là danh từ không đếm được. Cultural/natural/world heritage là các kết hợp phổ biến.","example":"Traditional songs form an important part of the community's cultural heritage."},{"number":95,"term":"monument","sourceTerm":"monument (n)","spoken":"monument","ipa":"monument /ˈmɑːnjumənt/","type":"noun","meaning":"tượng đài tưởng niệm","definition":"A structure, statue, or site that honors a person or event or has historical importance.","note":"Monument có thể là công trình tưởng niệm hoặc di tích có giá trị lịch sử.","example":"The stone monument honors villagers who protected the town during the war."},{"number":96,"term":"tangible >< intangible","sourceTerm":"tangible >< intangible","spoken":"tangible , intangible","ipa":"tangible /ˈtændʒəbəl/ · intangible /ˌɪˈntændʒəbəl/","type":"adjective · adjective","meaning":"hữu hình, có thể chạm thấy · vô hình, phi vật thể","definition":"Tangible heritage can be physically touched; intangible heritage consists of non-physical traditions, knowledge, or skills.","note":"Dùng cặp tangible heritage >< intangible heritage để phân biệt di sản vật thể và phi vật thể.","example":"The temple is tangible heritage, while the songs performed inside it are intangible heritage."},{"number":97,"term":"craft","sourceTerm":"craft (n)","spoken":"craft","ipa":"craft /kræft/","type":"noun","meaning":"nghệ thuật thủ công","definition":"An activity requiring skill to make things by hand, or an object produced through that activity.","note":"Craft có thể chỉ hoạt động, nghề/kĩ năng hoặc sản phẩm thủ công tùy văn cảnh.","example":"Basket weaving is a traditional craft that requires years of practice."},{"number":98,"term":"contrast · in contrast to","sourceTerm":"contrast · in contrast to","spoken":"contrast , in contrast to","ipa":"contrast v /kənˈtræst/ · n /ˈkɑːntræst/ · in contrast to /ɪn ˈkɑːntræst tuː/","type":"verb · noun · preposition","meaning":"sự tương phản; làm nổi bật sự khác biệt · trái lại; tương phản với","definition":"A clear difference between things; to contrast is to compare them in order to show that difference.","note":"Contrast A with B. A contrasts with B. In contrast to + danh từ/cụm danh từ.","example":"Modern clothing contrasts with traditional dress; in contrast to factory-made items, each local item is woven by hand."},{"number":99,"term":"martial art","sourceTerm":"martial art (N phr)","spoken":"martial art","ipa":"martial /ˈmɑːrʃəl/ · art /ɑːrt/","type":"noun · phrase / pattern","meaning":"võ thuật (nói chung)","definition":"A system of fighting techniques practiced as a sport, discipline, or means of self-defense.","note":"Martial art ở số ít chỉ một môn. Martial arts ở số nhiều chỉ võ thuật nói chung.","example":"The martial art combines physical training with rules about respect and self-control."},{"number":100,"term":"hospitable · hospitality","sourceTerm":"hospitable · hospitality","spoken":"hospitable , hospitality","ipa":"hospitable /ˌhɑːˈspɪtəbəl/ · hospitality /ˌhɑːspəˈtæləti/","type":"noun · adjective","meaning":"hiếu khách · lòng hiếu khách, sự tiếp đón","definition":"Friendly and generous toward guests; hospitality is the quality or practice of welcoming them.","note":"Hospitable to/toward sb. Show/offer hospitality to sb.","example":"The hospitable villagers offered visitors a meal, and their hospitality made everyone feel welcome."},{"number":101,"term":"cultural identity","sourceTerm":"cultural identity","spoken":"cultural identity","ipa":"cultural /ˈkʌltʃɚəl/ · identity /aɪˈdɛntɪˌti/","type":"word / phrase","meaning":"bản sắc văn hóa","definition":"The shared traditions, values, language, and practices through which a group understands itself.","note":"","example":"Traditional dance helps young people express and preserve their cultural identity."},{"number":102,"term":"decline ~ decrease","sourceTerm":"decline (v, n) ~ decrease (v, n)","spoken":"decline , decrease","ipa":"decline v,n /dɪˈklaɪn/ · decrease v /dɪˈkriːs/ · n /ˈdiːkriːs/","type":"verb · verb · noun · noun","meaning":"giảm, suy giảm; sự suy giảm","definition":"To become lower in number, amount, quality, or strength; decrease can also mean to make something lower, and both can name a reduction.","note":"Decline thường là nội động từ hoặc danh từ. Decrease có thể là nội động từ, ngoại động từ hoặc danh từ. Decline còn có nghĩa lịch sự từ chối trong văn cảnh khác.","example":"Participation in the ritual declined as the village population decreased."},{"number":103,"term":"weave","sourceTerm":"weave (v)","spoken":"weave","ipa":"weave /wiːv/","type":"verb","meaning":"dệt (vải)","definition":"To make cloth or another material by crossing threads or narrow pieces over and under one another.","note":"Weave – wove – woven. Weave A into B mang nghĩa dệt hoặc đan A thành B.","example":"Skilled workers weave colored threads into cloth using wooden frames."},{"number":104,"term":"cuisine # dish","sourceTerm":"cuisine # dish","spoken":"cuisine , dish","ipa":"cuisine /kwɪˈziːn/ · dish /dɪʃ/","type":"noun · noun","meaning":"nền ẩm thực, phong cách nấu ăn · món ăn cụ thể","definition":"Cuisine is a culture's or region's style of cooking; a dish is one particular prepared item of food.","note":"Cuisine nói về phong cách ẩm thực. Dish là một món ăn cụ thể.","example":"The region's cuisine reflects its coastal history, and its best-known dish is a spicy fish soup."},{"number":105,"term":"convince sb to do sth ~ persuade sb to do sth","sourceTerm":"convince (v) sb to do sth ~ persuade (v) sb to do sth","spoken":"convince somebody to do something , persuade somebody to do something","ipa":"convince /kəˈnvɪns/ · persuade /pɚˈsweɪd/","type":"verb · verb · phrase / pattern","meaning":"thuyết phục ai làm gì","definition":"To cause someone to believe something or agree to take a particular action.","note":"Convince sb that + mệnh đề nhấn mạnh làm ai tin. Persuade sb to do sth nhấn mạnh thuyết phục ai hành động. Convince sb to do sth cũng được dùng phổ biến.","example":"Community leaders convinced young people to learn the craft and persuaded schools to include it in local programs."},{"number":106,"term":"endure","sourceTerm":"endure (v)","spoken":"endure","ipa":"endure /ɛˈndjʊr/","type":"verb","meaning":"chịu đựng; tồn tại bền bỉ","definition":"To suffer something difficult patiently, or to continue to exist despite hardship.","note":"Endure + khó khăn/đau đớn. Endure còn có thể không có tân ngữ khi mang nghĩa tồn tại bền bỉ.","example":"The community endured years of conflict, yet its traditions endured."},{"number":107,"term":"violent · violence","sourceTerm":"violent · violence","spoken":"violent , violence","ipa":"violent /ˈvaɪələnt/ · violence /ˈvaɪələns/","type":"noun · adjective","meaning":"mang tính bạo lực, dữ dội · bạo lực","definition":"Using or involving physical force intended to hurt or damage; violence is such behavior or force.","note":"Violent là tính từ. Violence là danh từ không đếm được.","example":"The tradition survived a violent period in which political violence affected many families."},{"number":108,"term":"basic · basis · on the basis of","sourceTerm":"basic · basis · on the basis of","spoken":"basic , basis , on the basis of","ipa":"basic /ˈbeɪsɪk/ · basis /ˈbeɪsəs/","type":"noun · adjective · preposition","meaning":"cơ bản, nền tảng · cơ sở, căn cứ · dựa trên, căn cứ vào","definition":"Basic means fundamental or simple; a basis is the main idea or support for something, and on the basis of means using it as a reason.","note":"Basic là tính từ. Basis là danh từ có số nhiều bases. On the basis of + danh từ/cụm danh từ.","example":"Respect is a basic value and the basis of the ritual; participants are chosen on the basis of their experience."},{"number":109,"term":"hard · hardship","sourceTerm":"hard · hardship","spoken":"hard , hardship","ipa":"hard /hɑːrd/ · hardship /ˈhɑːrdʃɪp/","type":"noun · adjective","meaning":"khó khăn, gian khổ · hoàn cảnh khó khăn, sự thiếu thốn","definition":"Hard means difficult; hardship is a condition that causes suffering or serious difficulty.","note":"Hard có nhiều nghĩa. Trong nhóm này, hard mang nghĩa khó khăn. Hardship thường nói về hoàn cảnh gây thiếu thốn hoặc đau khổ.","example":"It was hard to continue the festival during the economic hardship."},{"number":110,"term":"diverse · diversity · cultural diversity","sourceTerm":"diverse · diversity · cultural diversity","spoken":"diverse , diversity , cultural diversity","ipa":"diverse /daɪˈvɝːs/ · diversity /dɪˈvɝːsɪti/ · cultural /ˈkʌltʃɚəl/","type":"noun · noun · adjective","meaning":"đa dạng · sự đa dạng · sự đa dạng văn hóa","definition":"Including many different types; diversity is the presence of variety, and cultural diversity is variety among cultures.","note":"Diverse + danh từ. Diversity of/among + danh từ. Học các từ cùng gốc và chọn đúng dạng theo vị trí trong câu.","example":"The city has a diverse population, and its cultural diversity is visible in public festivals."},{"number":111,"term":"practice","sourceTerm":"practice (n) · (v)","spoken":"practice","ipa":"practice /ˈpræktəs/","type":"verb · noun","meaning":"hoạt động, tập quán · thực hiện, luyện tập","definition":"A customary activity or accepted way of doing something; as a verb, to perform or repeat an activity to improve.","note":"Trong tiếng Anh-Mỹ, practice dùng cho cả danh từ và động từ. Xác định nghĩa theo vị trí và văn cảnh.","example":"The annual ceremony is an ancient practice, and young performers practice its movements every week."},{"number":112,"term":"promote","sourceTerm":"promote (v)","spoken":"promote","ipa":"promote /prəˈmoʊt/","type":"verb","meaning":"thăng chức; tăng cường, thúc đẩy; quảng cáo, quảng bá","definition":"To support or encourage the growth of something, advertise it, or give someone a higher position.","note":"Promote a product/cause mang nghĩa quảng bá hoặc thúc đẩy. Promote sb to a position mang nghĩa thăng chức cho ai.","example":"The museum promotes traditional crafts through exhibitions, while the organization promotes skilled staff to leadership positions."},{"number":113,"term":"gradual · gradually >< sudden · suddenly","sourceTerm":"gradual · gradually >< sudden · suddenly","spoken":"gradual , gradually , sudden , suddenly","ipa":"gradual /ˈɡrædʒuəl/ · gradually /ˈɡrædʒuəli/ · sudden /ˈsʌdən/ · suddenly /ˈsʌdənli/","type":"adjective · adjective · adverb · adverb","meaning":"diễn ra từ từ (tính từ) · một cách dần dần · đột ngột, bất ngờ (tính từ) · một cách đột ngột","definition":"Gradual and gradually describe slow change over time; sudden and suddenly describe quick, unexpected change.","note":"Gradual + danh từ. Gradually là trạng từ. Sudden + danh từ. Suddenly là trạng từ.","example":"The gradual decline in participation took place over generations rather than as a sudden change."},{"number":114,"term":"inspire · inspiration","sourceTerm":"inspire · inspiration","spoken":"inspire , inspiration","ipa":"inspire /ˌɪˈnspaɪr/ · inspiration /ˌɪnspɚˈeɪʃən/","type":"verb · noun","meaning":"truyền cảm hứng · sự cảm hứng; nguồn cảm hứng","definition":"To give someone the desire or confidence to create or act; inspiration is that influence or a source of it.","note":"Inspire sb to do sth. Inspire sb with sth. Inspiration for/to sb.","example":"The artist's work inspired students, and local history became their main source of inspiration."},{"number":115,"term":"enemy ~ opponent","sourceTerm":"enemy ~ opponent","spoken":"enemy , opponent","ipa":"enemy /ˈɛnəmi/ · opponent /əˈpoʊnənt/","type":"noun · noun","meaning":"kẻ thù ~ đối thủ trong thi đấu hoặc tranh luận","definition":"An enemy is actively hostile or at war; an opponent competes or argues against someone without necessarily being hostile.","note":"Enemy nhấn mạnh đối thủ thù địch. Opponent là đối thủ trong thi đấu hoặc tranh luận và không nhất thiết là kẻ thù.","example":"The community hid sacred objects from the enemy, while festival opponents only argued that the event cost too much."},{"number":116,"term":"military · military force # police force","sourceTerm":"military · military force # police force","spoken":"military , military force , police force","ipa":"military /ˈmɪləˌtɛri/ · force /fɔːrs/ · police /pəˈliːs/","type":"noun · noun · adjective","meaning":"thuộc quân đội, quân sự · lực lượng quân đội · lực lượng cảnh sát","definition":"Military relates to a country's armed services; a military force fights or defends, while a police force enforces civil law.","note":"Military force thuộc quân đội. Police force thuộc lực lượng thực thi pháp luật dân sự.","example":"A military force guarded the border, while the local police force protected the festival."},{"number":117,"term":"define · definition","sourceTerm":"define · definition","spoken":"define , definition","ipa":"define /dɪˈfaɪn/ · definition /ˌdɛfəˈnɪʃən/","type":"verb · noun","meaning":"định nghĩa, xác định rõ · lời hoặc nội dung định nghĩa","definition":"To state the exact meaning or essential qualities of something; a definition is that statement.","note":"Define A as B dùng để định nghĩa A là B. A definition of + thuật ngữ/khái niệm.","example":"The report defines cultural heritage broadly and gives a clear definition of each category."}],"pronunciationFocus":[{"entryNumber":98,"points":[{"category":"word-stress","note":"contrast là động từ /kənˈtræst/ khi nhấn âm hai; danh từ trong in contrast to là /ˈkɑːntræst/ và nhấn âm đầu"},{"category":"final-sound","note":"contrast kết thúc bằng cụm /st/"}]},{"entryNumber":99,"points":[{"category":"linking","note":"Đọc liền martial‿art, nối /l/ cuối martial sang nguyên âm đầu của art"}]},{"entryNumber":100,"points":[{"category":"word-stress","note":"hospitable nhấn âm tiết thứ hai; hospitality chuyển trọng âm sang âm tiết chứa /tæl/"}]},{"entryNumber":102,"points":[{"category":"word-stress","note":"decrease nhấn âm cuối /dɪˈkriːs/ khi là động từ, nhưng nhấn âm đầu /ˈdiːkriːs/ khi là danh từ"},{"category":"final-sound","note":"decrease kết thúc bằng /s/"}]},{"entryNumber":104,"points":[{"category":"word-stress","note":"cuisine nhấn âm tiết thứ hai và giữ nguyên âm dài /iː/"},{"category":"final-sound","note":"cuisine kết thúc bằng /n/; dish kết thúc bằng /ʃ/"}]},{"entryNumber":105,"points":[{"category":"final-sound","note":"convince kết thúc bằng /ns/; persuade kết thúc bằng /d/"}]},{"entryNumber":114,"points":[{"category":"word-stress","note":"inspire nhấn âm tiết thứ hai; inspiration chuyển trọng âm sang âm tiết chứa /eɪ/"}]}]}};
